        ("if item not in self.items:", "Проверка «такого элемента ещё нет». Благодаря ей повторы не попадают в множество."),
        ("self.items.append(item)", "Добавляет элемент в конец списка."),
        ("return item in self.items", "Проверка принадлежности: возвращает True или False."),
        ("result = MySet()", "Создаёт новое пустое множество для результата. Исходные множества при объединении и пересечении не меняются."),
        ("for item in self.items:", "Перебор всех элементов множества."),
        ("def __str__(self)", "Задаёт, как множество печатается: все элементы через запятую в фигурных скобках. text[:-2] отрезает последние два символа (лишние запятая и пробел)."),
        ("class Lesson", "Одна пара: поля day, number и course."),
